189	ipcMain.handle('gh:prCommentReply', (_event, opts) => {
190	  const repo = safeArg(opts?.repo);
191	  const prNumber = safeArg(opts?.prNumber);
192	  const body = String(opts?.body || '');
193	  const inReplyToId = Number(opts?.inReplyToId) || null;
194	  try {
195	    if (inReplyToId) {
196	      // Reply to a review comment thread.
197	      // body stays a `-f` string (double-quoted so spaces survive execSync's
198	      // join — safeArg() already rejected double-quote characters).
199	      // in_reply_to MUST use uppercase `-F`: `-f` would send the id as a
200	      // string, but GitHub's API schema requires it to be a JSON number
201	      // (HTTP 422 "is not a number" otherwise).
202	      const result = runGh([
203	        'api', `repos/${repo}/pulls/${prNumber}/comments`,
204	        '--method', 'POST',
205	        '-f', `body="${body}"`,
206	        '-F', `in_reply_to=${inReplyToId}`,
207	      ]);
208	      return { ok: true, comment: JSON.parse(result || '{}') };
209	    } else {
210	      // General issue comment
211	      const result = runGh([
212	        'api', `repos/${repo}/issues/${prNumber}/comments`,
213	        '--method', 'POST',
214	        '-f', `body="${body}"`,
215	      ]);
